import{_ as e,o as a,c as l,a2 as r}from"./chunks/framework.Crpw6aS5.js";const b=JSON.parse('{"title":"通用再保险（General Re / Gen Re）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/通用再保险.md","filePath":"03_companies/通用再保险.md"}'),h={name:"03_companies/通用再保险.md"};function d(i,t,o,n,s,m){return a(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="通用再保险-general-re-gen-re" tabindex="-1">通用再保险（General Re / Gen Re） <a class="header-anchor" href="#通用再保险-general-re-gen-re" aria-label="Permalink to &quot;通用再保险（General Re / Gen Re）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>General Reinsurance Corporation (Gen Re)</td></tr><tr><td>行业</td><td>再保险</td></tr><tr><td>成立年份</td><td>1921年</td></tr><tr><td>总部</td><td>康涅狄格州斯坦福德</td></tr><tr><td>CEO</td><td>Ron Ferguson（罗恩·弗格森）</td></tr><tr><td>伯克希尔持股</td><td>100%</td></tr><tr><td>收购价格</td><td>约220亿美元（1998年）</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>全球最大再保险公司之一，为各类保险公司提供风险转移和分散服务。再保险业务覆盖人寿险、财产险、意外险等多个领域，帮助原保险公司管理巨灾风险和承保能力。</p><h2 id="收购故事" tabindex="-1">收购故事 <a class="header-anchor" href="#收购故事" aria-label="Permalink to &quot;收购故事&quot;">​</a></h2><h3 id="收购背景" tabindex="-1">收购背景 <a class="header-anchor" href="#收购背景" aria-label="Permalink to &quot;收购背景&quot;">​</a></h3><ul><li><strong>1998年</strong>：伯克希尔以约220亿美元完成收购，成为当时保险业最大并购之一</li><li>收购时 Gen Re 已是全球再保险市场的领军企业</li><li>此前 Gen Re 与德国科隆再保险（Cologne Re）完成合并</li></ul><h3 id="收购逻辑" tabindex="-1">收购逻辑 <a class="header-anchor" href="#收购逻辑" aria-label="Permalink to &quot;收购逻辑&quot;">​</a></h3><ol><li><strong>浮存金优势</strong>：再保险公司持有大量浮存金，可用于投资</li><li><strong>行业地位</strong>：全球最大再保险公司之一，品牌信誉卓越</li><li><strong>协同效应</strong>：与伯克希尔现有保险业务形成互补</li></ol><h3 id="整合困难" tabindex="-1">整合困难 <a class="header-anchor" href="#整合困难" aria-label="Permalink to &quot;整合困难&quot;">​</a></h3><p>然而，收购后的整合远未达到预期：</p><ul><li><strong>浮存金质量下降</strong>：合并后业务结构变化导致浮存金质量不如预期</li><li><strong>合约定价问题</strong>：部分合同定价偏低，影响承保利润</li><li><strong>管理挑战</strong>：与 Cologne Re 合并带来的文化整合和业务协调问题</li><li><strong>会计问题</strong>：2005年曝光的虚假交易丑闻，严重损害公司声誉</li></ul><h2 id="修复与整顿" tabindex="-1">修复与整顿 <a class="header-anchor" href="#修复与整顿" aria-label="Permalink to &quot;修复与整顿&quot;">​</a></h2><h3 id="阿吉特·贾恩的介入" tabindex="-1">阿吉特·贾恩的介入 <a class="header-anchor" href="#阿吉特·贾恩的介入" aria-label="Permalink to &quot;阿吉特·贾恩的介入&quot;">​</a></h3><p>在 Gen Re 深陷困境之际，<a href="/04_people/阿吉特·贾恩.html">阿吉特·贾恩</a> 发挥了关键作用：</p><ul><li>凭借其卓越的保险精算能力和承保纪律</li><li>帮助 Gen Re 重塑核保文化</li><li>逐步恢复承保纪律，淘汰低利润甚至亏损的业务</li><li>在其领导下，Gen Re 的承保业绩逐步回归正轨</li></ul><h3 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>姓名</th><th>职位</th><th>贡献</th></tr></thead><tbody><tr><td><a href="/04_people/罗恩·弗格森.html">罗恩·弗格森</a></td><td>CEO</td><td>长期领导 Gen Re，经历收购与整合全过程</td></tr><tr><td><a href="/04_people/阿吉特·贾恩.html">阿吉特·贾恩</a></td><td>再保险业务负责人</td><td>帮助重建承保纪律，恢复盈利能力</td></tr></tbody></table><h2 id="巴菲特反思" tabindex="-1">巴菲特反思 <a class="header-anchor" href="#巴菲特反思" aria-label="Permalink to &quot;巴菲特反思&quot;">​</a></h2><p>巴菲特多次在股东信中公开反思 Gen Re 收购的教训：</p><blockquote><p>1998年的 Gen Re 收购是伯克希尔历史上最昂贵的错误之一。我们为这家公司支付了过高的价格，同时低估了整合的难度。</p></blockquote><blockquote><p>浮存金的规模并不等于浮存金的质量。在评估再保险公司时，承保纪律比浮存金数量更重要。</p></blockquote><h3 id="教训总结" tabindex="-1">教训总结 <a class="header-anchor" href="#教训总结" aria-label="Permalink to &quot;教训总结&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>教训</th></tr></thead><tbody><tr><td>支付价格过高</td><td>优质资产也需要合理价格</td></tr><tr><td>整合难度低估</td><td>大型并购需充分评估协同效应</td></tr><tr><td>浮存金质量</td><td>规模不等于质量，纪律比数量重要</td></tr><tr><td>合约定价</td><td>再保险必须坚持承保纪律</td></tr></tbody></table><h2 id="财务表现-摘录" tabindex="-1">财务表现（摘录） <a class="header-anchor" href="#财务表现-摘录" aria-label="Permalink to &quot;财务表现（摘录）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年份</th><th>承保利润</th><th>浮存金</th><th>备注</th></tr></thead><tbody><tr><td>1998（收购年）</td><td>-</td><td>高</td><td>收购后整合开始</td></tr><tr><td>2001-2004</td><td>亏损</td><td>下降</td><td>承保纪律松散，问题暴露</td></tr><tr><td>2005</td><td>丑闻</td><td>-</td><td>虚假交易曝光</td></tr><tr><td>2005年后</td><td>改善</td><td>稳定</td><td><a href="/04_people/阿吉特·贾恩.html">阿吉特·贾恩</a>介入整顿</td></tr></tbody></table><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1998, 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> - 母公司</li><li><a href="/04_people/阿吉特·贾恩.html">阿吉特·贾恩</a> - 拯救 Gen Re 的关键人物</li><li><a href="/04_people/罗恩·弗格森.html">罗恩·弗格森</a> - Gen Re CEO</li></ul><hr><p><em>最后更新：2026-04-12</em></p><h2 id="相关信件" tabindex="-1">相关信件 <a class="header-anchor" href="#相关信件" aria-label="Permalink to &quot;相关信件&quot;">​</a></h2><ul><li><a href="./../01_letters/1998年/翻译.html">1998年</a></li><li><a href="./../01_letters/1999年/翻译.html">1999年</a></li><li><a href="./../01_letters/2000年/翻译.html">2000年</a></li><li><a href="./../01_letters/2001年/翻译.html">2001年</a></li><li><a href="./../01_letters/2002年/翻译.html">2002年</a></li><li><a href="./../01_letters/2003年/翻译.html">2003年</a></li><li><a href="./../01_letters/2004年/翻译.html">2004年</a></li><li><a href="./../01_letters/2005年/翻译.html">2005年</a></li><li><a href="./../01_letters/2006年/翻译.html">2006年</a></li><li><a href="./../01_letters/2007年/翻译.html">2007年</a></li><li><a href="./../01_letters/2008年/翻译.html">2008年</a></li><li><a href="./../01_letters/2009年/翻译.html">2009年</a></li><li><a href="./../01_letters/2010年/翻译.html">2010年</a></li><li><a href="./../01_letters/2011年/翻译.html">2011年</a></li><li><a href="./../01_letters/2012年/翻译.html">2012年</a></li><li><a href="./../01_letters/2013年/翻译.html">2013年</a></li><li><a href="./../01_letters/2014年/翻译.html">2014年</a></li><li><a href="./../01_letters/2015年/翻译.html">2015年</a></li><li><a href="./../01_letters/2016年/翻译.html">2016年</a></li><li><a href="./../01_letters/2017年/翻译.html">2017年</a></li><li><a href="./../01_letters/2018年/翻译.html">2018年</a></li><li><a href="./../01_letters/2019年/翻译.html">2019年</a></li><li><a href="./../01_letters/2020年/翻译.html">2020年</a></li></ul>',35)])])}const c=e(h,[["render",d]]);export{b as __pageData,c as default};
